SELECT id
  FROM tenants AS t
  WHERE t.admin_user_forms_id = #{formId}

SELECT id
  FROM tenants AS t
  WHERE t.multi_factor_voice_messengers_id = #{messengerId}


WITH ids AS (
	SELECT id
	FROM tenants t


      AND LOWER(t.name) LIKE #{name}



    ORDER BY ${orderBy}


    LIMIT #{numberOfResults}


    OFFSET #{startRow}

)

INNER JOIN ids ON ids.id = t.id


    ORDER BY ${orderBy}, t.id, ct.sequence ASC, tvk.type, tvk.is_default DESC, tvk.keys_id


    ORDER BY t.id, ct.sequence ASC, tvk.type, tvk.is_default DESC, tvk.keys_id

SELECT COUNT(*)
FROM tenants t


    AND LOWER(t.name) LIKE #{name}


WHERE name = #{name}

  AND id != #{id}

ORDER BY t.id, ct.sequence ASC, tvk.type, tvk.is_default DESC, tvk.keys_id

SELECT tenants_id
  FROM connectors_tenants
  WHERE connectors_id = #{connectorId}

